// Game based on IDEA.md – Meteor Dodge
// Canvas with id="game"
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = canvas.clientWidth;
canvas.height = canvas.clientHeight;

// ----- Player -----
const ship = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  r: 12,
  angle: 0,
  vx: 0,
  vy: 0,
  thrust: 0.1,
  rotSpeed: 0.08,
  fuel: 100,
};

